      return subtle.encrypt(
        { name: algorithmName, iv: iv, additionalData: ad },
        key,
        plaintext
      );
    })
    .then(function (encrypted) {
      return subtle.decrypt(
        { name: algorithmName, iv: iv, additionalData: ad },
