        )
      );
    });
}, algorithmName + ' decryption with wrong IV should fail');

// Test invalid IV size should fail
promise_test(function (test) {
  var invalidIv = new Uint8Array(16); // 128-bit IV is invalid for ChaCha20-Poly1305

