function main(): void {
// U+212A is the Kelvin Sign

function makeSalt() {
  return crypto.getRandomValues(new Uint8Array(32));
}

async function makeKey(algorithm) {
  const keyData = new Uint8Array([]);
  return crypto.subtle.importKey("raw", keyData, algorithm, false, ["deriveBits"]);
}

promise_test(async (t) => {
  const algorithm = {
    name: "H\u212ADF",
    hash: "SHA-256",
    salt: makeSalt(),
    info: new TextEncoder().encode(''),
  };
  const key = await makeKey("HKDF");
  const p = crypto.subtle.deriveBits(algorithm, key, 256);
  return promise_rejects_dom(t, "NotSupportedError", p, algorithm.name);
}, `"H<U+212A>DF" does not match "HKDF"`);

promise_test(async (t) => {
  const algorithm = {
    name: "PB\u212ADF2",
    hash: "SHA-256",
    iterations: 1,
    salt: makeSalt(),
  };
  const key = await makeKey("PBKDF2");
  const p = crypto.subtle.deriveBits(algorithm, key, 256);
  return promise_rejects_dom(t, "NotSupportedError", p, algorithm.name);
}, `"PB<U+212A>DF2" does not match "PBKDF2"`);

promise_test(async (t) => {
  const algorithm = {name: "AES-\u212AW", length: 256};
  const p = crypto.subtle.generateKey(algorithm, false, ["wrapKey"]);
  return promise_rejects_dom(t, "NotSupportedError", p, algorithm.name);
}, `"AES-<U+212A>W" does not match "AES-KW"`);

promise_test(async (t) => {
  const algorithm = {
    name: "RSASSA-P\u212ACS1-V1_5",
    modulusLength: 2048,
    publicExponent: new Uint8Array([3]),
    hash: "SHA-256",
  };
  const p = crypto.subtle.generateKey(algorithm, false, ["sign"]);
  return promise_rejects_dom(t, "NotSupportedError", p, algorithm.name);
}, `"RSASSA-P<U+212A>CS1-V1_5" does not match "RSASSA-PKCS1-V1_5"`);
}
main();

function main(): void {
// Run for enough iterations that we're likely to catch edge-cases, like
// failing to set a reserved bit:
const iterations = 256;
// Track all the UUIDs generated during test run, bail if we ever collide:
const uuids = new Set()
function randomUUID() {
    const uuid = self.crypto.randomUUID();
    if (uuids.has(uuid)) {
        throw new Error(`uuid collision ${uuid}`)
    }
    uuids.add(uuid);
    return uuid;
}

// UUID is in namespace format (16 bytes separated by dashes):
test(function() {
    const UUIDRegex = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/
    for (let i = 0; i < iterations; i++) {
        assert_true(UUIDRegex.test(randomUUID()));
    }
}, "namespace format");

// Set the 4 most significant bits of array[6], which represent the UUID
// version, to 0b0100:
test(function() {
    for (let i = 0; i < iterations; i++) {
        let value = parseInt(randomUUID().split('-')[2].slice(0, 2), 16);
        value &= 0b11110000;
        assert_true(value === 0b01000000);
    }
}, "version set");

// Set the 2 most significant bits of array[8], which represent the UUID
// variant, to 0b10:
test(function() {
    for (let i = 0; i < iterations; i++) {
        // Grab the byte representing array[8]:
        let value = parseInt(randomUUID().split('-')[3].slice(0, 2), 16);
        value &= 0b11000000
        assert_true(value === 0b10000000);
    }
}, "variant set");
}
main();

